"""3Sum — sort + two pointers.

Fix the smallest element, then two-pointer the remainder for the pair that
completes the triplet. Skipping equal neighbours at every level is what keeps
the result set free of duplicates without a hash set.

Time: O(n^2)   Space: O(1) beyond the output
"""
from typing import List


class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        n, out = len(nums), []
        for i in range(n - 2):
            if nums[i] > 0:
                break                      # smallest is positive -> no zero sum left
            if i > 0 and nums[i] == nums[i - 1]:
                continue                   # skip duplicate anchors
            lo, hi = i + 1, n - 1
            while lo < hi:
                total = nums[i] + nums[lo] + nums[hi]
                if total < 0:
                    lo += 1
                elif total > 0:
                    hi -= 1
                else:
                    out.append([nums[i], nums[lo], nums[hi]])
                    lo += 1
                    hi -= 1
                    while lo < hi and nums[lo] == nums[lo - 1]:
                        lo += 1
                    while lo < hi and nums[hi] == nums[hi + 1]:
                        hi -= 1
        return out
